import {start as startCngSession} from './characters/cng/campaign.js';
import { showAreaPicker } from './shared/map/layout.js';
import { start as startBusMission } from './characters/bus/campaign.js';
const $=s=>document.querySelector(s);
let saved={};try{saved=JSON.parse(localStorage.getItem('dhaka-welcome')||'{}')}catch{}
let lang=saved.lang==='bn'?'bn':'en', selected=saved.role||null, sound=false;
const words={welcome:['Welcome','স্বাগতম'],characters:['Characters 05','চরিত্র ০৫'],how:['How to play','খেলার নিয়ম'],loading:['Finding a little space in the traffic…','জ্যামের মাঝে একটু জায়গা খুঁজছি…'],eyebrow:['A LITTLE CHAOS. A LOT OF DHAKA.','একটু বিশৃঙ্খলা। অনেকখানি ঢাকা।'],description:['Five lives. One city. Absolutely no chill.\nFind your place in the beautiful madness.','পাঁচটি জীবন। একটি শহর। বিরামহীন ব্যস্ততা।\nএই মজার বিশৃঙ্খলায় নিজের গল্প খুঁজে নিন।'],choose:['Choose your character','আপনার চরিত্র বেছে নিন'],meet:['Meet the madness','ঢাকার গল্প জানুন'],free:['Free to explore','সবার জন্য উন্মুক্ত'],local:['Made for our streets','আমাদের রাস্তার গল্প'],street:['EVERY STREET HAS A STORY.','প্রতিটি রাস্তার একটি গল্প আছে।'],step:['01 / PICK YOUR PERSPECTIVE','০১ / আপনার দৃষ্টিভঙ্গি বেছে নিন'],who:['Who are you in this city?','এই শহরে আপনি কে?'],roleHint:['Same streets. Different stories.\nPick a character to discover their rules.','একই রাস্তা। ভিন্ন গল্প।\nনিয়ম জানতে একটি চরিত্র বেছে নিন।'],selectHint:['Your story is waiting. Choose a character above.','আপনার গল্প অপেক্ষায়। উপরে একটি চরিত্র বেছে নিন।'],rules:['View character rules','চরিত্রের নিয়ম দেখুন'],prototype:['BUS MISSION 01 / v0.2','বাস মিশন ০১ / v0.2'],footer:['Fictional chaos. Real love for Dhaka.','কাল্পনিক বিশৃঙ্খলা। ঢাকার জন্য সত্যিকারের ভালোবাসা।'],replay:['Replay intro ↻','শুরুর পর্দা আবার দেখুন ↻']};
const roles=[
{id:'bus',name:['Bus driver','বাস ড্রাইভার'],sub:['You drive. Your helper handles the gate.','আপনি চালান, হেলপার গেট সামলাবেন।'],tag:['DRIVER + HELPER','ড্রাইভার + হেলপার'],color:'#514537',accent:'#d6a456',quote:['“Pichhone jayga ase!”','“পিছনে জায়গা আছে!”'],rules:[['Drive the bus and stop at marked bays. Your capped helper works at the gate and boards passengers while you are parked.','বাস চালান ও চিহ্নিত স্টপে থামুন। টুপি পরা হেলপার গেটে থাকবেন এবং দাঁড়ানো বাসে যাত্রী তুলবেন।'],['Choose only your starting area. Drive freely with your helper through the shared Mirpur–Agargaon city.','শুধু শুরুর এলাকা বেছে নিন। হেলপারকে সঙ্গে নিয়ে মিরপুর–আগারগাঁও শহরে নিজের মতো চালান।'],['Safe stops and clever crowd management earn respect. Hitting a pedestrian fails the mission.','নিরাপদ স্টপ ও বুদ্ধিদীপ্ত ব্যবস্থাপনায় সম্মান বাড়ে। পথচারীকে ধাক্কা দিলে মিশন ব্যর্থ।']]},
{id:'cng',name:['CNG driver','সিএনজি চালক'],sub:['Every destination is a debate.','গন্তব্য নিয়ে একটু আলোচনা হোক।'],tag:['THE NEGOTIATOR','দরদামের ওস্তাদ'],color:'#2a4a41',accent:'#8cba83',quote:['“Oi dike jamu na, mama!”','“ওই দিকে যামু না, মামা!”'],rules:[['Check the destination, agree on a fair fare, then accept your passenger.','গন্তব্য জানুন, ন্যায্য ভাড়া ঠিক করুন, তারপর যাত্রী নিন।'],['Choose a legal route and turn only where permitted. Watch the refusal meter.','বৈধ রুট বেছে নিন ও অনুমোদিত স্থানে মোড় নিন। প্রত্যাখ্যানের মিটারে নজর রাখুন।'],['Resolve fare disputes calmly. Clear roads and safe arrivals earn skill points.','শান্তভাবে ভাড়ার বিরোধ মেটান। পথ খোলা রাখা ও নিরাপদে পৌঁছানোয় দক্ষতা বাড়ে।']]},
{id:'rickshaw',name:['Rickshaw puller','রিকশাচালক'],sub:['Small lanes. Big ambitions.','ছোট গলি, বড় স্বপ্ন।'],tag:['THE LANE LEGEND','গলির ওস্তাদ'],color:'#3f4146',accent:'#d1a3a5',quote:['“Mama, shortcut chini!”','“মামা, শর্টকাট চিনি!”'],rules:[['Balance pedaling and stamina. Save some energy for the next lane.','প্যাডেল ও শক্তির ভারসাম্য রাখুন। পরের গলির জন্য শক্তি বাঁচান।'],['Use the bell thoughtfully and follow the direction of the road.','প্রয়োজনে বেল বাজান ও রাস্তার সঠিক দিকে চলুন।'],['Find a safe route through narrow lanes. Protect your passengers and give pedestrians room.','সরু গলিতে নিরাপদ পথ খুঁজুন। যাত্রীকে সুরক্ষিত রাখুন ও পথচারীকে জায়গা দিন।']]},
{id:'biker',name:['Biker','বাইকার'],sub:['Delivery time. Decision time.','ডেলিভারির তাড়া, সিদ্ধান্তের পালা।'],tag:['THE QUICK THINKER','দ্রুত সিদ্ধান্তের ওস্তাদ'],color:'#424543',accent:'#d5aa77',quote:['“Bhai, ektu side!”','“ভাই, একটু সাইড!”'],rules:[['Wear your helmet, collect the parcel, and check the delivery route.','হেলমেট পরুন, পার্সেল নিন ও ডেলিভারির রুট দেখুন।'],['Stay in the road lanes and obey signals. The footpath is for pedestrians.','রাস্তার লেনে থাকুন ও সিগন্যাল মানুন। ফুটপাত পথচারীদের জন্য।'],['Deliver carefully around traffic and hazards. Dangerous shortcuts reset the run.','যানবাহন ও বাধা এড়িয়ে সাবধানে পৌঁছান। বিপজ্জনক শর্টকাটে আবার শুরু করতে হবে।']]},
{id:'shop',name:['Footpath shopkeeper','ফুটপাতের দোকানদার'],sub:['Big business. Little space.','ছোট জায়গা, বড় ব্যবসা।'],tag:['THE SPACE STRATEGIST','জায়গা সামলানোর ওস্তাদ'],color:'#4b3b35',accent:'#cf9574',quote:['“Dokan na, public service!”','“দোকান না, পাবলিক সার্ভিস!”'],rules:[['Arrange your stall inside the marked area. Keep a clear walking path.','চিহ্নিত জায়গায় দোকান সাজান। হাঁটার পথ খোলা রাখুন।'],['Serve customers and manage the queue without blocking the footpath.','ফুটপাত না আটকে ক্রেতাদের সেবা দিন ও সারি সামলান।'],['Adapt your layout as the crowd changes. Clearing obstructions earns respect.','ভিড় অনুযায়ী দোকানের বিন্যাস বদলান। বাধা সরালে সম্মান বাড়ে।']]}];
const t=v=>v[lang==='bn'?1:0];
const svg=(body,view='0 0 240 150')=>`<svg viewBox="${view}" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">${body}</svg>`;
const wheel=(x,y,r=14)=>`<circle cx="${x}" cy="${y}" r="${r}" fill="#142124" stroke="#839185" stroke-width="3"/><circle cx="${x}" cy="${y}" r="${r*.35}" fill="#d2c398"/>`;
function art(id){let b='';const ground='<ellipse cx="120" cy="132" rx="87" ry="7" fill="#101b1d55"/>';
if(id==='bus')b=`<path d="M28 64Q28 45 46 45H188Q207 45 210 66L216 115H27Z" fill="#d1a45b" stroke="#1a2a29" stroke-width="3"/><path d="M32 88H211V109H30Z" fill="#8d4940"/><path d="M39 54H71V81H39ZM79 54H111V81H79ZM119 54H151V81H119ZM160 54H190L198 81H160Z" fill="#294345" stroke="#a8b6a0" stroke-width="2"/><path d="M174 86H197V116H174Z" fill="#273936"/><path d="M45 95H153" stroke="#f5cf7f" stroke-width="3"/>${wheel(61,117)}${wheel(181,117)}<text x="89" y="40" fill="#ead1a0" font-size="10">ঢাকা পরিবহন</text><path d="M151 97L143 122M151 97L160 121M151 81V100M151 87L168 76" stroke="#d1b599" stroke-width="6" stroke-linecap="round"/><circle cx="151" cy="73" r="9" fill="#be9470"/><path d="M141 70Q151 57 160 70" fill="#172a29"/>`;
if(id==='cng')b=`<path d="M58 79L74 48Q117 33 163 49L188 94V119H49V99Z" fill="#689975" stroke="#1a302a" stroke-width="3"/><path d="M76 51Q117 40 159 52L168 80H67Z" fill="#1e3736" stroke="#b7b994" stroke-width="3"/><path d="M71 83H170V112H71Z" fill="#7ca27a"/><path d="M137 83V112M76 91H117" stroke="#28473d" stroke-width="3"/><path d="M161 52L146 80H169" fill="#b9c9aa"/><path d="M57 96H68V104H53M176 96H186V104H176" fill="#f3cd73"/>${wheel(76,119)}${wheel(167,119)}<path d="M83 46Q119 31 155 47" stroke="#e4c976" stroke-width="4" fill="none"/><text x="94" y="103" fill="#244737" font-size="9">মামার CNG</text>`;
if(id==='rickshaw')b=`${wheel(66,116,22)}${wheel(179,116,22)}<path d="M66 116L100 88L124 116H66L88 72M100 88H139L157 112H179L159 74" fill="none" stroke="#d1b16b" stroke-width="4"/><path d="M123 91V65Q121 26 155 30Q190 29 191 66V96Z" fill="#984f55" stroke="#d0ac8b" stroke-width="3"/><path d="M133 67Q132 42 156 42Q179 42 180 67Z" fill="#2c4742"/><path d="M128 85H184V101H128Z" fill="#cfb16e"/><path d="M144 87L155 74L168 87L155 97Z" fill="#768e6a"/><circle cx="100" cy="57" r="9" fill="#c49e7f"/><path d="M101 68L112 86L90 100L85 115M110 84L123 72" fill="none" stroke="#9cad99" stroke-width="7" stroke-linecap="round"/><path d="M93 51Q101 43 110 54" fill="#ded0a4"/>`;
if(id==='biker')b=`${wheel(64,117,22)}${wheel(177,117,22)}<path d="M64 117L99 87L137 117H64M177 117L152 77H134" fill="none" stroke="#ba9c6b" stroke-width="5"/><path d="M81 94L118 91L141 104L156 90L134 80H105Z" fill="#b27652" stroke="#172e2b" stroke-width="3"/><path d="M121 62L132 82L153 77M121 65L111 88L128 112" fill="none" stroke="#aab6a5" stroke-width="9" stroke-linecap="round"/><path d="M108 61L126 57L137 76L117 82Z" fill="#d2ad6d"/><circle cx="116" cy="46" r="13" fill="#bda77c"/><path d="M104 46Q100 27 118 28Q134 29 132 46Z" fill="#243d3d"/><path d="M118 38H132V45H118Z" fill="#97afac"/><rect x="49" y="65" width="37" height="30" rx="3" fill="#c8a67a"/><path d="M67 66V94M50 76H85" stroke="#84684e" stroke-width="2"/>`;
if(id==='shop')b=`<path d="M61 61V127M181 61V127" stroke="#b69e76" stroke-width="5"/><path d="M45 62L65 33H179L199 62Z" fill="#a85946"/><path d="M75 33L64 62H90L95 33M120 33V62H145L141 33M165 33L178 62H198L179 33" fill="#d3b67a"/><path d="M45 62Q55 78 65 62Q77 78 90 62Q104 78 119 62Q133 78 146 62Q162 78 178 62Q190 78 199 62" fill="#a85946"/><rect x="56" y="97" width="132" height="34" rx="2" fill="#658276"/><rect x="51" y="93" width="142" height="8" fill="#d1b685"/><path d="M75 93V78H93V93M79 75H90M135 93V80H149V93M153 93V80H167V93" fill="#d5c49d" stroke="#c3ab7d" stroke-width="2"/><circle cx="119" cy="69" r="10" fill="#bb9679"/><path d="M105 91V83Q119 72 133 83V93" fill="#c9ab70"/><path class="smoke" d="M82 69Q75 63 82 57M143 72Q138 66 144 60" fill="none" stroke="#c1cab1" stroke-width="2"/><text x="93" y="121" fill="#e8d5a4" font-size="12">চা ও আড্ডা</text>`;
return svg(ground+b)}
function city(){let buildings='';for(let i=0;i<13;i++){let x=i*49-18,y=105+(i%4)*16,h=140+(i%3)*17;buildings+=`<path d="M${x} ${y}h43v${h}h-43Z" fill="${['#2a4544','#354c47','#3c5049'][i%3]}"/><path d="M${x+3} ${y-7}h35v7h-35Z" fill="#536255"/>`;for(let a=0;a<3;a++)for(let b=0;b<4;b++)buildings+=`<rect x="${x+7+a*11}" y="${y+13+b*23}" width="5" height="11" fill="${(a+b+i)%3?'#132e31':'#c3a568'}" opacity=".65"/>`}
return svg(`<defs><linearGradient id="sky" x2="0" y2="1"><stop stop-color="#193336"/><stop offset="1" stop-color="#788471"/></linearGradient><radialGradient id="moon"><stop stop-color="#eed7a2" stop-opacity=".18"/><stop offset="1" stop-color="#eed7a2" stop-opacity="0"/></radialGradient><linearGradient id="road" x2="0" y2="1"><stop stop-color="#344743"/><stop offset="1" stop-color="#152729"/></linearGradient></defs><rect width="600" height="470" fill="url(#sky)"/><circle cx="430" cy="105" r="95" fill="url(#moon)"/><circle cx="430" cy="105" r="26" fill="#ded0a3" opacity=".8"/><path d="M0 167H600M0 197H600" stroke="#a1ac8a" opacity=".08"/>${buildings}<path d="M210 219L388 219L650 470H-50Z" fill="url(#road)"/><path d="M205 222L-30 470M394 223L629 470" stroke="#8d967b" stroke-width="13"/><path d="M299 244L294 266M292 283L282 322M276 345L262 398M253 424L241 470" stroke="#beaf79" stroke-width="4" opacity=".5"/><path d="M0 264L176 227M600 273L425 232" stroke="#738771" stroke-width="16"/><path d="M0 285L174 239M600 294L427 246" stroke="#1d3433" stroke-width="19"/><g transform="translate(14 170) scale(.6)">${art('shop').replace(/<\/?svg[^>]*>/g,'')}</g><g class="traffic"><g transform="translate(217 197) scale(.8)">${art('bus').replace(/<\/?svg[^>]*>/g,'')}</g></g><g transform="translate(326 283) scale(.85)">${art('cng').replace(/<\/?svg[^>]*>/g,'')}</g><g transform="translate(84 278) scale(.73)">${art('rickshaw').replace(/<\/?svg[^>]*>/g,'')}</g><g transform="translate(418 219) scale(.48)">${art('biker').replace(/<\/?svg[^>]*>/g,'')}</g><path d="M56 293V126Q56 110 77 110H125M514 324V147Q514 130 492 130H462" fill="none" stroke="#192e2d" stroke-width="5"/><path class="lamp" d="M107 112L55 280L179 249L124 112M462 132L419 277L550 302L477 132" fill="#e3c788" opacity=".08"/><path d="M108 111H127M461 131H480" stroke="#eed6a0" stroke-width="5"/><path d="M0 86Q270 147 600 70M0 95Q270 156 600 79" stroke="#142a2b" fill="none" stroke-width="2"/><path d="M0 65Q280 128 600 43" stroke="#8f9276" fill="none" opacity=".5"/><g fill="#baa06d"><path d="M87 83l6 16l8-13ZM143 93l6 16l8-13ZM202 99l6 16l8-13ZM262 100l6 16l8-13ZM322 96l6 16l8-13ZM382 88l6 16l8-13ZM442 76l6 16l8-13Z"/></g><path d="M466 310V239H492V310" fill="#233a33"/><rect x="459" y="235" width="40" height="33" fill="#bfa76e" transform="rotate(-5 479 251)"/><text x="464" y="255" font-size="11" fill="#263c35">ধীরে চলুন</text><path d="M0 441Q70 403 100 470H0M600 422Q530 398 509 470H600" fill="#263f35"/>`,'0 0 600 470')}
$('#city').innerHTML=city();
function save(){try{localStorage.setItem('dhaka-welcome',JSON.stringify({lang,role:selected,startPlaceId:saved.startPlaceId||'mirpur12',reduced:document.body.classList.contains('reduce-motion')}))}catch{}}
function render(){document.documentElement.lang=lang;document.querySelectorAll('[data-i]').forEach(el=>{const v=words[el.dataset.i];if(v){el.textContent=t(v);el.style.whiteSpace='pre-line'}});document.querySelectorAll('[data-lang]').forEach(b=>{b.classList.toggle('selected',b.dataset.lang===lang);b.setAttribute('aria-pressed',b.dataset.lang===lang)});$('#character-grid').innerHTML=roles.map((r,i)=>`<button class="character-card ${selected===r.id?'selected':''}" data-role="${r.id}" aria-pressed="${selected===r.id}" aria-label="${t(r.name)}: ${lang==='en'?'view rules':'নিয়ম দেখুন'}"><div class="character-art" style="--card:${r.color}" data-num="0${i+1}">${art(r.id)}<span class="role-tag">${lang==='en'?'AVAILABLE':'উন্মুক্ত'}</span></div><div class="card-content"><div class="card-title">${t(r.name)}<b>${selected===r.id?'✓':'↗'}</b></div><p class="card-subtitle">${t(r.sub)}</p><div class="card-bottom"><span>${t(r.tag)}</span><span>0${i+1}</span></div></div></button>`).join('');document.querySelectorAll('[data-role]').forEach(b=>b.onclick=()=>{selected=b.dataset.role;save();render();showRole()});$('#review').disabled=!selected;if(selected){const r=roles.find(r=>r.id===selected);if(r)$('#selection-text').textContent=(lang==='en'?'Your perspective: ':'আপনার চরিত্র: ')+t(r.name)}save()}
const dialog=$('#dialog');function open(content){$('#dialog-content').innerHTML=content;dialog.showModal()}function close(){dialog.close()}$('.close').onclick=close;dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close()}});
function showRole(){const r=roles.find(r=>r.id===selected);if(!r)return;open(`<div class="eyebrow">${lang==='en'?'YOUR PERSPECTIVE / CHARACTER RULES':'আপনার চরিত্র / খেলার নিয়ম'}</div><h2>${t(r.name)}</h2><p>${t(r.quote)}</p><div class="modal-art" style="--card:${r.color}">${art(r.id)}</div><ol class="rule-list">${r.rules.map(v=>`<li>${t(v)}</li>`).join('')}</ol><p class="modal-note">${lang==='en'?'Skill and respect reward safe decisions. Chaos is a fictional comedy meter.':'নিরাপদ সিদ্ধান্তে দক্ষতা ও সম্মান বাড়ে। বিশৃঙ্খলা কেবল কাল্পনিক হাস্যরসের মিটার।'}</p><div class="modal-actions"><button class="primary" id="confirm-role">${(r.id==='bus'||r.id==='cng')?(lang==='en'?'Choose starting area':'শুরুর এলাকা বাছুন'):(lang==='en'?'This is my character':'এই চরিত্রই আমার')} <b>✓</b></button><button class="text-button" id="back-role">${lang==='en'?'Go back':'ফিরে যান'}</button></div>`);$('#back-role').onclick=close;$('#confirm-role').onclick=()=>{close();save();if(r.id==='bus'||r.id==='cng'){showAreaPicker({language:lang,selected:saved.startPlaceId||'mirpur12',onStart:({startPlaceId})=>{saved.startPlaceId=startPlaceId;save();(r.id==='cng'?startCngSession:startBusMission)({language:lang,startPlaceId,onExit:()=>render()})}})}else{toast((lang==='en'?'Character saved: ':'চরিত্র সংরক্ষিত: ')+t(r.name))}}}
let toastTimer;function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200)}
function info(){open(`<div class="eyebrow">${lang==='en'?'WELCOME TO DHAKA':'ঢাকায় স্বাগতম'}</div><h2>${lang==='en'?'One city. Five stories.':'এক শহর। পাঁচ গল্প।'}</h2><p>${lang==='en'?'A playful traffic satire about the people who keep Dhaka moving. Choose your perspective, learn your role, and make a little room for everyone.':'ঢাকার প্রতিদিনের মানুষ ও রাস্তার গল্প নিয়ে মজার একটি গেম। চরিত্র বেছে নিন, নিয়ম জানুন এবং সবার জন্য একটু জায়গা রাখুন।'}</p><ol class="rule-list"><li>${lang==='en'?'Choose any of the five characters. All are available.':'পাঁচটি চরিত্রের যেকোনো একটি বেছে নিন। সবাই উন্মুক্ত।'}</li><li>${lang==='en'?'Read the character briefing and confirm your choice.':'চরিত্রের নিয়ম পড়ে আপনার পছন্দ নিশ্চিত করুন।'}</li><li>${lang==='en'?'Change language or motion preferences at any time. Your choice stays on this browser.':'যেকোনো সময় ভাষা বা অ্যানিমেশনের সেটিংস বদলান। পছন্দ এই ব্রাউজারে সংরক্ষিত থাকে।'}</li></ol><p class="modal-note">${lang==='en'?'Bus driver now includes Mission 1 in a continuous 3D city. Select Bus driver to start; the other characters currently have selection and rules only.':'বাস ড্রাইভার বেছে নিয়ে বিরামহীন থ্রিডি শহরে মিশন ১ খেলুন। অন্য চরিত্রগুলোতে এখন শুধু নির্বাচন ও নিয়ম আছে।'}</p>`)}
$('#intro').onclick=info;$('#review').onclick=showRole;
$('#choose').onclick=()=>{setNav('characters');$('#characters').scrollIntoView({behavior:'smooth'});$('#character-grid button').focus({preventScroll:true})};
function setNav(view){document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view))}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{setNav(b.dataset.view);if(b.dataset.view==='how')info();else if(b.dataset.view==='characters')$('#characters').scrollIntoView({behavior:'smooth'});else window.scrollTo({top:0,behavior:'smooth'})});
document.querySelectorAll('[data-lang]').forEach(b=>b.onclick=()=>{lang=b.dataset.lang;render()});
$('#settings').onclick=()=>{open(`<div class="eyebrow">${lang==='en'?'MAKE YOURSELF AT HOME':'নিজের মতো সাজান'}</div><h2>${lang==='en'?'Settings':'সেটিংস'}</h2><label class="toggle">${lang==='en'?'Reduce animations':'অ্যানিমেশন কমান'}<input id="motion" type="checkbox" ${document.body.classList.contains('reduce-motion')?'checked':''}></label><p>${lang==='en'?'Language and character preferences are saved on this device. No account needed.':'ভাষা ও চরিত্রের পছন্দ এই ডিভাইসে সংরক্ষিত থাকে। অ্যাকাউন্ট লাগে না।'}</p>`);$('#motion').onchange=e=>{document.body.classList.toggle('reduce-motion',e.target.checked);save()}};
let audio,osc,gain;$('#sound').onclick=()=>{sound=!sound;try{if(sound){audio||=new(window.AudioContext||window.webkitAudioContext)();audio.resume();osc=audio.createOscillator();gain=audio.createGain();osc.type='sine';osc.frequency.value=110;gain.gain.value=.018;osc.connect(gain);gain.connect(audio.destination);osc.start()}else{osc?.stop()}}catch{sound=false}$('#sound').setAttribute('aria-pressed',String(sound));$('#sound').setAttribute('aria-label',sound?'Mute sound':'Enable sound');$('.sound-slash').style.display=sound?'none':'';toast(lang==='en'?(sound?'Ambient sound on':'Sound off'):(sound?'আবহসংগীত চালু':'শব্দ বন্ধ'))};
function loading(){const loader=$('#loader');loader.classList.remove('done');setTimeout(()=>loader.classList.add('done'),1900)}$('#replay').onclick=loading;if(saved.reduced)document.body.classList.add('reduce-motion');render();loading();
